{
  "verdict": "request_changes",
  "summary": "candidate.py implements ordered() with string key sorting, not numeric ordering.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The implementation sorts by string representation of the version, resulting in lexicographic order rather than numeric order. This violates the contract which requires ascending numeric sorting.",
      "evidence": "For input events = [{'version': '10'}, {'version': '2'}], candidate.ordered(events) returns [{'version': '10'}, {'version': '2'}] whereas the correct order should be [{'version': '2'}, {'version': '10'}]."
    }
  ]
}
